        connecting_rod: connecting_rod,
        rod_journal: rod_journal,
        exhaust_system: exhaust_system,
        intake: intake,
        ignition_wire: ignition_wire,
        cylinder_bank: this,
        sound_attenuation: sound_attenuation,
        primary_length: primary_length
